out = {}; err = []
for vid, s in src.items():
    if vid not in T: err.append('missing '+vid); continue
    ph, no, q, a, last = T[vid]
    pm = {p['text']: ph[i] for i, p in enumerate(s['phrases'])}
    nm = {n: no[i] for i, n in enumerate(s['nouns'])}
    if len(ph)!=len(s['phrases']) or len(no)!=len(s['nouns']): err.append('count '+vid)
    rc = []
    for i, r in enumerate(s['recall']):
        if r in pm: rc.append(pm[r])
        elif r in nm: rc.append(nm[r])
        elif i == len(s['recall'])-1: rc.append(last)
        else: err.append(f'recall {vid}: {r}')
    out[vid] = {"phrases": ph, "nouns": no, "question": q, "answer": a, "captions": {}, "recall": rc}
print(err)
json.dump(out, open(f'{H}/tr/b002/es/de.json','w'), ensure_ascii=False, indent=1)
